-- ================================================================
-- 069_seed_interacoes_nutricao.sql
-- Secção 11 (Nutrição):
--   11.1 Nutrição entérica (glicose — fonte glucídica)
--   11.2 Nutrição parentérica (aminoácidos, emulsão lipídica)
--   11.3 Vitaminas e sais minerais (vitamina D3, ácido ascórbico,
--        carbonato de cálcio, cloreto de potássio, sulfato de
--        magnésio, sulfato de zinco)
-- Novos (9): glicose, aminoacidos, emulsao_lipidica, colecalciferol,
--            acido_ascorbico, carbonato_calcio, cloreto_potassio,
--            sulfato_magnesio, zinco.
-- Nota: ferro, ácido fólico, cianocobalamina (B12) e fitomenadiona
--       (vitamina K1) já foram criados na migração 064 (Hematologia).
-- Aplicar manualmente no Supabase (SQL editor). Idempotente (ON CONFLICT).
-- Fonte fármaco-fármaco: DailyMed (FDA) — setIDs validados na API.
-- Fonte 3 dimensões: EMC-UK (MHRA) canónico; fallback DailyMed (FDA).
-- ================================================================

-- ----------------------------------------------------------------
-- 1. Fármacos novos
-- ----------------------------------------------------------------
INSERT INTO public.drugs (slug, name_pt, name_en, class_pt, class_en, aliases, status, sort_order) VALUES
  ('glicose', 'Glicose (dextrose)', 'Glucose (dextrose)', 'Nutrição entérica (fonte glucídica)', 'Enteral nutrition (carbohydrate source)', ARRAY['dextrose', 'Glicose', 'glucose', 'Glucose 5%'], 'published', 168),
  ('aminoacidos', 'Aminoácidos', 'Amino acids', 'Nutrição parentérica (solução de aminoácidos)', 'Parenteral nutrition (amino acid solution)', ARRAY['aminoácidos', 'amino acids', 'Aminoplasmal', 'amino acids injection'], 'published', 169),
  ('emulsao_lipidica', 'Emulsão lipídica', 'Lipid emulsion', 'Nutrição parentérica (emulsão lipídica)', 'Parenteral nutrition (lipid emulsion)', ARRAY['Intralipid', 'Lipofundin', 'emulsão lipídica', 'lipid emulsion'], 'published', 170),
  ('colecalciferol', 'Colecalciferol (vitamina D3)', 'Cholecalciferol (vitamin D3)', 'Vitamina lipossolúvel (D3)', 'Fat-soluble vitamin (D3)', ARRAY['vitamina D3', 'vitamin D3', 'cholecalciferol', 'Desunin'], 'published', 171),
  ('acido_ascorbico', 'Ácido ascórbico (vitamina C)', 'Ascorbic acid (vitamin C)', 'Vitamina hidrossolúvel (C)', 'Water-soluble vitamin (C)', ARRAY['vitamina C', 'vitamin C', 'ascorbic acid', 'ascorbato'], 'published', 172),
  ('carbonato_calcio', 'Carbonato de cálcio', 'Calcium carbonate', 'Sais minerais (cálcio)', 'Mineral supplement (calcium)', ARRAY['cálcio', 'calcium', 'carbonato de cálcio', 'Adcal', 'Calcichew'], 'published', 173),
  ('cloreto_potassio', 'Cloreto de potássio', 'Potassium chloride', 'Eletrólito (potássio)', 'Electrolyte (potassium)', ARRAY['potássio', 'potassium', 'cloreto de potássio', 'Sando-K'], 'published', 174),
  ('sulfato_magnesio', 'Sulfato de magnésio', 'Magnesium sulfate', 'Eletrólito (magnésio)', 'Electrolyte (magnesium)', ARRAY['magnésio', 'magnesium', 'sulfato de magnésio', 'Epsom'], 'published', 175),
  ('zinco', 'Zinco (sulfato de zinco)', 'Zinc (zinc sulfate)', 'Oligoelemento (zinco)', 'Trace element (zinc)', ARRAY['sulfato de zinco', 'zinc sulfate', 'zinc', 'zinco'], 'published', 176);

